import React, { useEffect, useRef, useState } from "react";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import BannerImage from "../../assets/banner/banner.png";
import { apisPath } from "../../utils/path";
import http, { uploadImage } from "../../services/utility";
import { useDispatch } from "react-redux";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";

export default function Banner() {
  const dispatch = useDispatch();
  const bannerFileUploadRef = useRef(null);
  const bannerFileUploadTabRef = useRef(null);
  const bannerFileUploadDesktopRef = useRef(null);
  const [bannerListItems, setBannerListItems] = useState([]);
  const [imageUrl, setImageUrl] = useState(null);
  const [imageUrlTab, setImageUrlTab] = useState(null);
  const [imageUrlDesktop, setImageUrlDesktop] = useState(null);
  const [navigationLink, setNavigationLink] = useState("");
  const [bannerType, setBannerType] = useState("Hero Slider");

  const bannerTypeOptions = [
    { value: "Hero Slider", label: "Hero Slider - For hero section slider banners" },
    { value: "Banner 1 Section", label: "Banner 1 Section - For home page banner section 1" },
    { value: "Banner 2 Section", label: "Banner 2 Section - For home page banner section 2" },
    { value: "Banner 3 Section", label: "Banner 3 Section - For home page banner section 3" }
  ];

  useEffect(() => {
    getData();
  }, []);

  const groupBannersByType = (banners) => {
    const grouped = {
      "Hero Slider": [],
      "Banner 1 Section": [],
      "Banner 2 Section": [],
      "Banner 3 Section": []
    };

    banners.forEach(banner => {
      const type = banner.type || "Hero Slider"; // Default to Hero Slider if no type
      if (grouped[type]) {
        grouped[type].push(banner);
      } else {
        // If type doesn't match our predefined types, add to Hero Slider as fallback
        grouped["Hero Slider"].push(banner);
      }
    });

    return grouped;
  };

  const getData = async () => {
    await http
      .get(apisPath?.admin?.banners)
      .then(async (res) => {
        var data = res?.data?.banner;

        for (let i = 0; i < data.length; i++) {
          data[i]["bannerImage"] = data[i]?.web;
        }

        setBannerListItems(data);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.banners}?id=${index}`)
      .then(async (res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const uploadData = async () => {
    const formData = {
      phone: imageUrl,
      tab: imageUrlTab,
      web: imageUrlDesktop,
      link: navigationLink ? [navigationLink] : [],
      type: bannerType,
    };

    await http
      .post(apisPath?.admin?.banners, formData)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        setImageUrl("");
        setImageUrlTab("");
        setImageUrlDesktop("");
        setNavigationLink("");
        setBannerType("Hero Slider");
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const UploadImage = async (e, nameFor) => {
    const file = e.target.files[0];
    if (file) {
      // Define size and dimension limits based on banner type
      let maxSize, maxWidth, maxHeight, recommendedText;

      switch (nameFor) {
        case "mobile":
          maxSize = 5 * 1024 * 1024; // 5MB
          maxWidth = 1500;
          maxHeight = 400;
          recommendedText = "Recommended: 1500x400px (Max 5MB, All image formats)";
          break;
        case "tab":
          maxSize = 5 * 1024 * 1024; // 5MB
          maxWidth = 1500;
          maxHeight = 400;
          recommendedText = "Recommended: 1500x400px (Max 5MB, All image formats)";
          break;
        case "desktop":
          maxSize = 5 * 1024 * 1024; // 5MB
          maxWidth = 1500;
          maxHeight = 400;
          recommendedText = "Recommended: 1500x400px (Max 5MB, All image formats)";
          break;
        default:
          return;
      }

      // Check file size
      if (file.size > maxSize) {
        dispatch(openTicker({
          title: "Error",
          body: `File size should not exceed ${maxSize / (1024 * 1024)}MB for ${nameFor} banner`
        }));
        return;
      }

      // Check file type
      if (!file.type.startsWith('image/')) {
        dispatch(openTicker({
          title: "Error",
          body: "Only image files are allowed"
        }));
        return;
      }

      // Check image dimensions
      const img = new Image();
      const objectUrl = URL.createObjectURL(file);

      img.onload = async function() {
        URL.revokeObjectURL(objectUrl);

        if (img.width > maxWidth || img.height > maxHeight) {
          dispatch(openTicker({
            title: "Error",
            body: `${nameFor.charAt(0).toUpperCase() + nameFor.slice(1)} banner dimensions should not exceed ${maxWidth}x${maxHeight}px. Your image is ${img.width}x${img.height}px. ${recommendedText}`
          }));
          return;
        }

        await uploadImage(e)
          .then((res) => {
            if (nameFor == "mobile") {
              setImageUrl(res?.url);
            } else if (nameFor == "tab") {
              setImageUrlTab(res?.url);
            } else if (nameFor == "desktop") {
              setImageUrlDesktop(res?.url);
            }
          })
          .catch((err) => {
            console.log(err);
          });
      };

      img.onerror = function() {
        URL.revokeObjectURL(objectUrl);
        dispatch(openTicker({ title: "Error", body: "Invalid image file" }));
      };

      img.src = objectUrl;
    }
  };

  return (
    <div className="banner">
      <h3 className="banner__heading page_heading">Banner</h3>
      <div className="banner__content">
        <div className="banner__content__upload">
          <div className="banner__content__upload__new_banner">
            <div
              className="banner__content__upload__new_banner__single"
              onClick={() => bannerFileUploadRef?.current?.click()}
            >
              {!imageUrl ? (
                <>
                  <FileUploadIcon />
                  <span>Upload brand logo for Mobile</span>
                  <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                    Recommended: 1500x400px (Max 5MB, All image formats)
                  </small>
                </>
              ) : (
                <img src={imageUrl} />
              )}
            </div>
            <div
              className="banner__content__upload__new_banner__single"
              onClick={() => bannerFileUploadTabRef?.current?.click()}
            >
              {!imageUrlTab ? (
                <>
                  <FileUploadIcon />
                  <span>Upload brand logo for Tablet</span>
                  <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                    Recommended: 1500x400px (Max 5MB, All image formats)
                  </small>
                </>
              ) : (
                <img src={imageUrlTab} />
              )}
            </div>
            <div
              className="banner__content__upload__new_banner__single"
              onClick={() => bannerFileUploadDesktopRef?.current?.click()}
            >
              {!imageUrlDesktop ? (
                <>
                  <FileUploadIcon />
                  <span>Upload brand logo for Desktop</span>
                  <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                    Recommended: 1500x400px (Max 5MB, All image formats)
                  </small>
                </>
              ) : (
                <img src={imageUrlDesktop} />
              )}
            </div>
          </div>
          <input
            type="file"
            style={{ display: "none" }}
            ref={bannerFileUploadRef}
            onChange={(e) => UploadImage(e, "mobile")}
          />
          <input
            type="file"
            style={{ display: "none" }}
            ref={bannerFileUploadTabRef}
            onChange={(e) => UploadImage(e, "tab")}
          />
          <input
            type="file"
            style={{ display: "none" }}
            ref={bannerFileUploadDesktopRef}
            onChange={(e) => UploadImage(e, "desktop")}
          />
          <div style={{ display: 'flex', gap: '20px', alignItems: 'flex-start' }}>
            <div className="add_blogs__content__heading" style={{ flex: 1 }}>
              <label htmlFor="banner_type">Banner Type</label>
              <select
                id="banner_type"
                name="banner_type"
                value={bannerType}
                onChange={(el) => setBannerType(el?.target?.value)}
                style={{
                  width: '100%',
                  padding: '8px 12px',
                  border: '1px solid #ddd',
                  borderRadius: '4px',
                  fontSize: '14px',
                  backgroundColor: '#fff'
                }}
              >
                {bannerTypeOptions.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>
            <div className="add_blogs__content__heading" style={{ flex: 1 }}>
              <label htmlFor="redirection_link">Redirection link</label>
              <input
                type="text"
                id="redirection_link"
                name="redirection_link"
                value={navigationLink}
                placeholder="Enter here"
                onChange={(el) => setNavigationLink(el?.target?.value)}
              />
            </div>
          </div>
          <button className="button-red" onClick={uploadData}>
            Upload
          </button>
        </div>

        <div className="banner__content__banner_list">
          <h4 className="banner__heading page_subheading">Banner list</h4>
          <div className="banner__content__banner_list__content">
            {bannerListItems?.length > 0 ? (
              (() => {
                const groupedBanners = groupBannersByType(bannerListItems);
                const bannerTypes = ["Hero Slider", "Banner 1 Section", "Banner 2 Section", "Banner 3 Section"];

                // Display Hero Slider section normally
                const heroSliderSection = (
                  <div key="Hero Slider" className="banner__type_section" style={{ marginBottom: '30px' }}>
                    <h5 style={{
                      fontSize: '18px',
                      fontWeight: 'bold',
                      marginBottom: '15px',
                      color: '#333'
                    }}>
                      Hero Slider ({groupedBanners["Hero Slider"].length} banner{groupedBanners["Hero Slider"].length !== 1 ? 's' : ''})
                    </h5>
                    {groupedBanners["Hero Slider"].length > 0 ? (
                      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '15px' }}>
                        {groupedBanners["Hero Slider"].map((item, index) => (
                          <BannerList
                            image={item?.bannerImage}
                            key={`Hero Slider-${index}`}
                            deleteData={() => deleteData(item?.id)}
                          />
                        ))}
                      </div>
                    ) : (
                      <div style={{
                        padding: '8px 12px',
                        color: '#666',
                        fontSize: '14px',
                        fontStyle: 'italic',
                        textAlign: 'center'
                      }}>
                        No Hero Slider banners found
                      </div>
                    )}
                  </div>
                );

                // Check if any of Banner 1, 2, 3 sections have banners
                const hasAnyBanners = groupedBanners["Banner 1 Section"].length > 0 ||
                                      groupedBanners["Banner 2 Section"].length > 0 ||
                                      groupedBanners["Banner 3 Section"].length > 0;

                const otherSections = hasAnyBanners ? (
                  // Display sections normally if any have banners
                  ["Banner 1 Section", "Banner 2 Section", "Banner 3 Section"].map(bannerType => (
                    <div key={bannerType} className="banner__type_section" style={{ marginBottom: '30px' }}>
                      <h5 style={{
                        fontSize: '18px',
                        fontWeight: 'bold',
                        marginBottom: '15px',
                        color: '#333'
                      }}>
                        {bannerType} ({groupedBanners[bannerType].length} banner{groupedBanners[bannerType].length !== 1 ? 's' : ''})
                      </h5>
                      {groupedBanners[bannerType].length > 0 ? (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '15px' }}>
                          {groupedBanners[bannerType].map((item, index) => (
                            <BannerList
                              image={item?.bannerImage}
                              key={`${bannerType}-${index}`}
                              deleteData={() => deleteData(item?.id)}
                            />
                          ))}
                        </div>
                      ) : (
                        <div style={{
                          padding: '8px 12px',
                          color: '#666',
                          fontSize: '14px',
                          fontStyle: 'italic',
                          textAlign: 'center'
                        }}>
                          No {bannerType} banners found
                        </div>
                      )}
                    </div>
                  ))
                ) : (
                  // Display all 3 sections horizontally if all are empty
                  <div className="banner__type_section" style={{ marginBottom: '30px' }}>
                    <div style={{ display: 'flex', gap: '20px', justifyContent: 'space-between' }}>
                      {["Banner 1 Section", "Banner 2 Section", "Banner 3 Section"].map(bannerType => (
                        <div key={bannerType} style={{ flex: 1 }}>
                          <h5 style={{
                            fontSize: '18px',
                            fontWeight: 'bold',
                            marginBottom: '10px',
                            color: '#333',
                            textAlign: 'center'
                          }}>
                            {bannerType} ({groupedBanners[bannerType].length} banner{groupedBanners[bannerType].length !== 1 ? 's' : ''})
                          </h5>
                          <div style={{
                            padding: '8px 12px',
                            color: '#666',
                            fontSize: '14px',
                            fontStyle: 'italic',
                            textAlign: 'center'
                          }}>
                            No {bannerType} banners found
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                );

                return [heroSliderSection, otherSections];
              })()
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

const BannerList = ({ image, deleteData }) => {
  return (
    <div className="banner_card">
      <div className="banner_card__banner_container">
        <img src={image} alt="Banner" />
      </div>
      <button className="button-red" onClick={deleteData}>
        Delete
      </button>
    </div>
  );
};
